<?php
require_once __DIR__.'/config.php';require_admin();
$id=(int)($_GET['id']??0);$place=$id?place_by_id($id):null;if($id&&!$place){flash('That place could not be found.','error');header('Location: admin.php');exit;}
$error='';$values=$place?:['name'=>'','category_id'=>'','short_description'=>'','description'=>'','distance_km'=>'','latitude'=>'','longitude'=>'','opening_info'=>'','entrance_fee'=>'','best_time'=>'','visit_minutes'=>60,'facilities'=>'','travel_tips'=>''];
if($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf();$values=array_merge($values,$_POST);$name=trim((string)($_POST['name']??''));$cat=(int)($_POST['category_id']??0);$distance=filter_var($_POST['distance_km']??null,FILTER_VALIDATE_FLOAT);$lat=filter_var($_POST['latitude']??null,FILTER_VALIDATE_FLOAT);$lon=filter_var($_POST['longitude']??null,FILTER_VALIDATE_FLOAT);$minutes=filter_var($_POST['visit_minutes']??null,FILTER_VALIDATE_INT);
 if($name===''||trim((string)($_POST['short_description']??''))===''||trim((string)($_POST['description']??''))===''||trim((string)($_POST['travel_tips']??''))==='')$error='Complete all required fields before saving.';
 elseif($distance===false || $distance<0 || $distance>25)$error='Distance must be between 0 and 25 km.';
 elseif($lat===false||$lat < -90||$lat>90||$lon===false||$lon < -180||$lon>180)$error='Enter valid latitude and longitude coordinates.';
 elseif(!$minutes||$minutes<1||$minutes>1440)$error='Visit duration must be between 1 and 1,440 minutes.';
 else {$catCheck=db()->prepare('SELECT id FROM categories WHERE id=?');$catCheck->execute([$cat]);if(!$catCheck->fetch())$error='Choose a valid category.';}
 if(!$error){$slug=trim((string)($_POST['slug']??''));if($slug==='')$slug=iconv('UTF-8','ASCII//TRANSLIT',$name);$slug=strtolower(trim(preg_replace('/[^a-zA-Z0-9]+/','-',$slug),'-'));$slug=substr($slug,0,175);$args=[$cat,$name,$slug,trim((string)$_POST['short_description']),trim((string)$_POST['description']),$distance,$lat,$lon,trim((string)$_POST['opening_info'])?:'Check locally before visiting',trim((string)$_POST['entrance_fee'])?:'Check locally',trim((string)$_POST['best_time'])?:'Daytime',$minutes,trim((string)$_POST['facilities'])?:'Information not confirmed',trim((string)$_POST['travel_tips']),trim((string)$_POST['image_url'])?:null];
  try {if($id){$args[]=$id;$sql='UPDATE places SET category_id=?,name=?,slug=?,short_description=?,description=?,distance_km=?,latitude=?,longitude=?,opening_info=?,entrance_fee=?,best_time=?,visit_minutes=?,facilities=?,travel_tips=?,image_url=? WHERE id=?';}else{$sql='INSERT INTO places(category_id,name,slug,short_description,description,distance_km,latitude,longitude,opening_info,entrance_fee,best_time,visit_minutes,facilities,travel_tips,image_url) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)';}db()->prepare($sql)->execute($args);flash($id?'Place updated.':'Place added to the guide.');header('Location: admin.php');exit;}catch(PDOException $ex){$error=$ex->getCode()==='23000'?'That place name or URL slug is already in use.':'We could not save this place. Please check the fields and try again.';}}
}
$pageTitle=$id?'Edit place':'Add a place';require __DIR__.'/includes/header.php';$cats=categories();
?>
<section class="form-page"><a class="back-link" href="admin.php">← Back to dashboard</a><div class="eyebrow eyebrow-dark">PLACE INFORMATION</div><h1><?= $id?'Edit a place':'Add a place' ?></h1><p class="form-intro">Share clear, helpful details for visitors planning a day around Gampola.</p><?php if($error): ?><div class="form-error" role="alert"><?= e($error) ?></div><?php endif; ?><form method="post" class="place-edit-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="edit-grid"><label class="wide">Place name *<input name="name" required maxlength="160" value="<?= e((string)$values['name']) ?>"></label><label>Category *<select name="category_id" required><option value="">Choose a category</option><?php foreach($cats as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$values['category_id']===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Distance from Gampola (km) *<input type="number" name="distance_km" min="0" max="25" step="0.1" required value="<?= e((string)$values['distance_km']) ?>"></label><label class="wide">Short description *<input name="short_description" maxlength="260" required value="<?= e((string)$values['short_description']) ?>"></label><label class="wide">Full description *<textarea name="description" rows="4" required><?= e((string)$values['description']) ?></textarea></label><label>Latitude *<input type="number" name="latitude" min="-90" max="90" step="any" required value="<?= e((string)$values['latitude']) ?>"></label><label>Longitude *<input type="number" name="longitude" min="-180" max="180" step="any" required value="<?= e((string)$values['longitude']) ?>"></label><label>Opening information<input name="opening_info" value="<?= e((string)$values['opening_info']) ?>"></label><label>Entrance fee<input name="entrance_fee" value="<?= e((string)$values['entrance_fee']) ?>"></label><label>Best time to visit<input name="best_time" value="<?= e((string)$values['best_time']) ?>"></label><label>Estimated visit duration (minutes)<input type="number" name="visit_minutes" min="1" max="1440" required value="<?= e((string)$values['visit_minutes']) ?>"></label><label class="wide">Facilities<input name="facilities" value="<?= e((string)$values['facilities']) ?>"></label><label class="wide">Travel tips *<textarea name="travel_tips" rows="3" required><?= e((string)$values['travel_tips']) ?></textarea></label><label class="wide">Image URL (optional)<input type="url" name="image_url" value="<?= e((string)($values['image_url']??'')) ?>" placeholder="https://..."></label></div><div class="form-actions"><a class="button button-outline" href="admin.php">Cancel</a><button class="button button-dark">Save place</button></div></form></section>
